        "content": "먹는 방식은 까다롭지 않아요. 0.5mg 캡슐 하나를 하루 한 차례, 물과 함께 쪼개지 않고 그대로 삼키면 그만이에요. 식약처 허가사항도 씹거나 분할하지 말라고 명시하면서, 식사 시점은 가리지 않아도 된다고 적어 뒀죠. 신장이 약하거나 고령이어도 용량을 별도로 조정하진 않아요.\n\n핵심은 빠뜨리지 않는 일관성이에요. 효소 억제 작용이 끊김 없이 쌓여야 유지되니까요. 체내 잔류가 길어 하루쯤 밀려도 농도가 곤두박질치진 않지만, 리듬을 지켜야 6개월째에 변화를 손에 쥐어요.\n\n분할 금지는 약효보다 안전 쪽 사안이에요. 이 성분은 피부로도 스며드는 탓에, 임신했거나 가임기인 여성이 새어 나온 내용물에 손대면 남자 태아 발달이 위협받을 수 있다고 허가사항이 경고해요. 연질캡슐인 만큼 겉면을 온전히 둔 채 다루는 게 핵심이죠. 간 기능 저하자는 권장용량 자료가 없으니, 삼키기 전 전문의 판단을 거치는 편이 안전해요."
