        answer:
          "둘 다예요. 식약처 허가 적응증에 양성 전립선 비대증 치료와 만 18~50세 남성형 탈모 치료가 함께 등재돼 있어요. 동일한 0.5mg 용량으로 두 적응증에 쓰여요. 탈모 목적이라면 피부과나 비뇨기과에서 처방받을 수 있어요.",
