          "유힐릭스정의 식약처 허가 적응증은 두 가지예요. 양성 전립선 비대증의 치료(증상 개선·급성 요저류 위험 감소·수술 필요성 감소)와, 성인 남성 만 18~50세의 남성형 탈모(androgenetic alopecia) 치료가 모두 허가돼 있어요.\n\n주성분인 두타스테리드 0.5mg은 5알파환원효소 1형과 2형을 동시에 억제해요. 테스토스테론이 DHT로 전환되는 걸 차단하고, DHT가 모낭을 위축시키는 과정을 끊는 구조예요. 탈모 목적으로 처방받으려면 만 18세 이상 50세 이하 남성이어야 하고, 50세를 넘는 남성에 대해서는 유효성 자료가 없다고 식약처 등록 정보에 명시돼 있어요.\n\n전립선 치료 목적이 아니라 탈모만 개선하고 싶은 경우에도 동일한 0.5mg 용량으로 처방받을 수 있어요. 단, 탈모 치료에 두타스테리드를 쓸지 피나스테리드를 쓸지는 처방 의사와 상의해서 결정해야 해요. 성분 선택이 곧 부작용 감수 수준과 연결되기 때문이에요.",
