        "content": "두테론정은 두타스테리드 0.5mg을 주성분으로 하는 정제예요. 동광제약(주)에서 만든 전문의약품이고, 식약처 품목번호는 201904188이에요. 식약처 허가사항을 보면 성인 남성(만 18~50세)의 남성형 탈모(androgenetic alopecia) 치료와 양성 전립선 비대증 치료에 쓰는 약이에요. 한 정에 두타스테리드가 0.5mg 들어 있어요.\n\n가격을 따지러 온 분이라면 한 가지만 먼저 짚고 갈게요. 두타스테리드 0.5mg은 성분과 함량이 정해져 있어서, 같은 0.5mg 제품끼리는 식약처가 허가한 효능·효과가 같아요. 즉 두테론정이든 다른 회사 두타스테리드 0.5mg이든 0.5mg이라는 함량이 같으면 기대하는 작용은 동일하다는 뜻이에요. 그래서 어떤 두타스테리드 0.5mg을 고르느냐는 효과보다 1정당 단가, 곧 가격 문제로 좁혀져요. 이 글이 두테론정 가격을 같은 성분 제품들과 나란히 놓고 보는 이유가 여기 있어요."
