        "content": "두테론정은 피부를 통해 흡수되기 때문에, 임신했거나 임신 가능성이 있는 여성은 이 약을 취급해서는 안 돼요. 부서지거나 깨진 조각을 만져서도 안 되고요. 여성, 18세 미만의 소아, 이 약이나 다른 5α-reductase 억제제에 과민증이 있는 환자에게는 투여하지 않아요. 식약처 허가사항 기준으로 정리한 금기예요.\n\n부작용을 보면, 남성형 탈모 위약대조 3상 임상시험 1(투여 6개월)에서 두타스테리드 0.5mg 투여군(n=184)의 발기기능장애는 10건(5%), 성욕감소는 4건(2%)으로 위약군보다 더 자주 보고됐어요. 국내 시판 후 사용성적조사에서는 남성형 탈모 치료로 투여받은 성인 남성 712명 중 약물유해반응 발현율이 9.3%(66명)였고, 성욕감소 9건, 소화불량 8건, 발기부전 7건 순이었어요. 또 이 약은 총 혈청 PSA 농도를 투여 6개월 후 약 50%까지 감소시켜서, 전립선암 검진 전에는 복용 사실을 의사에게 알려야 해요. 마지막 복용 후 최소 6개월이 지날 때까지 헌혈도 하면 안 돼요."
