        "content": "값부터 짚으면, 30캡슐 들이 한 통 기준가가 6,000원이에요. 한 알로 나누면 200원꼴이고, 하루 한 알이라 한 통이면 거의 한 달치예요. 두타스테리드 0.5mg으로 식약처에 등록된 동일 성분만 45종이나 되는데, 알당 단가로 줄 세우면 두타칸연질캡슐은 맨 아래 가격 구간에 놓여요.\n\n같은 성분이어도 알당 값은 폭이 넓어요. 적게는 200원, 많게는 1,267원까지 벌어지죠. 휴메리나정, 케이두타다트정, 유힐릭스정도 30정 6,000원에 알당 200원이라, 두타칸연질캡슐과 한 덩어리 최저가 그룹이에요. 전문의약품이니 6,000원이 끝은 아니고 진료비가 따로 들죠. 질환이 있다면 진료 때 약값과 간 기능 검사를 함께 상의하면 좋아요. 위 금액은 기준가이고, 약국 실거래 최저가는 아래 버튼에서 확인하세요."
