        "content": "두타엘정의 효과는 며칠 만에 눈에 보이지 않고, 몇 달 단위로 천천히 드러나요. 식약처 허가사항에 실린 남성형 탈모 임상시험이 6개월짜리 위약대조 설계로 진행됐다는 점이 그 시간 감각을 알려주는 단서예요.\n\n허가사항에 함께 실린 전립선비대증 자료를 보면 약효가 쌓이는 속도를 짐작할 수 있어요. 두타스테리드는 PSA 수치를 투여 3개월 후 약 40%, 투여 6개월 후 약 50%까지 낮춰요. 호르몬 경로에 미치는 변화가 한두 주가 아니라 분기 단위로 누적된다는 뜻이네요.\n\n반감기도 길어요. 허가사항은 이 약의 반감기를 약 3~5주로 적고 있죠. 매일 1정을 복용하면 혈중 농도가 일정 수준에 오르기까지 시간이 걸리고, 반대로 끊은 뒤에도 한동안 남아요. 그래서 효과 판단은 한두 달이 아니라 6개월 꾸준한 복용 뒤에 하는 게 맞아요. 정제냐 연질캡슐이냐는 이 발현 속도를 바꾸지 않죠. 복용 전후 두피 사진을 같은 조건에서 찍어두면 변화를 객관적으로 비교하기 좋아요."
