        "title": "두타엘정 효과를 보려면 어떻게 복용해야 하나요?",
        "content": "두타엘정은 1일 1회 1정(0.5mg)을 통째로 삼켜 복용해요. 식약처 허가사항의 용법대로 씹거나 쪼개지 않고 그대로 삼키는 게 핵심이죠. 식사와 관계없이 복용할 수 있어서, 아침이든 저녁이든 본인이 지키기 쉬운 시간으로 정하면 돼요.\n\n정제를 쪼개면 안 되는 이유는 효과가 아니라 안전 때문이에요. 허가사항 경고에 따르면 이 약은 피부로도 흡수되죠. 부서진 조각을 임신했거나 임신 가능성이 있는 여성이 만지면 남자 태아에게 위험할 수 있어요. 그래서 정제 상태 그대로 다뤄야 해요.\n\n반감기가 길어서 하루 정도 깜빡해도 혈중 농도가 급격히 떨어지진 않아요. 그래도 매일 같은 흐름으로 복용하는 편이 효과를 안정적으로 끌어올리죠. 신장애 환자나 노인 환자는 용량을 따로 조절할 필요가 없다고 허가사항에 적혀 있어요. 다만 간장애 환자에서의 권장용량은 확립돼 있지 않으니, 약 선택과 변경은 의사와 상의하세요."
