        "content": "식약처 허가사항의 권장용량은 1일 1회 1정(0.5mg)이에요. 1단계는 한 알을 충분한 물과 함께 그대로 넘기는 거예요. 허가사항은 이 약을 씹거나 쪼개지 않고 통째로 삼켜 복용하라고 적고 있어요. 입에서 굴려 녹이거나 반으로 잘라 먹는 건 허가된 방식이 아니에요. 2단계가 이 글의 핵심인데, 복용 시점을 정하는 거예요. 이 약은 식사와 관계없이 복용할 수 있어서 끼니에 맞출 필요가 없어요. 시간이 자유로운 만큼, 거꾸로 본인이 매일 지킬 시간을 직접 정해줘야 해요. 3단계는 용량 조절 여부 확인이에요. 신장애 환자나 노인 환자에서 용량을 조절할 필요는 없다고 허가사항에 적혀 있어요. 다만 간장애 환자에게 투여한 자료가 없어서, 간장애 환자에서의 권장용량은 확립돼 있지 않아요. 정리하면 물과 함께 통째로, 1일 1회 1정, 식사 무관, 이 세 가지가 뼈대예요. 매일 빠뜨리지 않는 게 가장 어려운 부분이라, 다음 단락에서 시간 잡는 법을 따로 풀어요. 약을 바꾸거나 멈출지는 의사와 상의하세요."
