          "피나에스정의 식약처 허가 적응증은 양성 전립샘 비대증이에요. 구체적으로는 양성 전립샘 비대증 증상의 개선, 비후된 전립샘의 퇴행 및 요류 개선, 급성 요폐 발생빈도 감소, 전립샘 경요도 절제술(TURP)을 포함한 수술 필요성 감소예요. 허가사항에 명시된 4가지 목적이 전부죠.\n\n주성분 피나스테리드는 5α-환원효소를 억제해 테스토스테론이 DHT(디하이드로테스토스테론)로 전환되는 걸 막아요. DHT는 전립샘 세포 증식을 유도하는 물질인데, 이 전환을 줄이면 비대해진 전립샘이 퇴행하고 배뇨 증상이 개선되는 원리예요. 단순해 보이지만 치료 효과가 즉각 나타나지는 않아요. 허가 기준상 증상이 개선되더라도 최소 6개월간의 치료가 필요해요.\n\n탈모와 연결 짓는 분이 많은데, 피나에스정은 탈모 치료 적응증을 받지 않은 제품이에요. 탈모 목적이라면 피나스테리드 1mg으로 허가받은 제품을 의사에게 처방받아야 해요. 5mg을 임의로 나눠 쓰는 방식은 허가 범위 밖이에요.",
