          "헤오나정은 만 18세 이상 41세 이하 성인 남성의 남성형 탈모증(안드로겐 탈모증) 치료에 식약처 허가를 받은 전문의약품이에요. 제조사는 오스코리아제약이고, 식약처 품목번호 201907328로 등록돼 있어요. 전문의약품이라 처방이 필요하죠.\n\n남성형 탈모는 테스토스테론이 DHT(디하이드로테스토스테론)로 전환되는 과정에서 모낭이 위축되면서 진행돼요. 헤오나정의 주성분 피나스테리드는 이 전환을 담당하는 5α-환원효소 2형을 선택적으로 억제해서 탈모 진행을 늦추고 발모를 촉진해요. 허가 문서에 따르면 용량을 증량해도 유효성이 더 커진다는 근거는 없어서, 1mg 이상 복용은 권장되지 않아요.\n\n여성, 소아, 만 41세 초과 남성에게는 유효성이 확립되지 않았어요. 원형탈모나 출산 관련 탈모에도 효과가 없으니, 어떤 유형의 탈모인지 피부과에서 먼저 진단받는 게 선행이에요.",
