          "식약처 허가 용법은 피나스테리드로서 1일 1회 5mg, 식사와 관계없이 경구 투여예요. 1정이 5mg이니 하루 1정이에요. 증상이 개선되더라도 최소 6개월간 치료를 유지해야 한다고 허가사항에 적혀 있어요. 효과가 즉시 나타나지 않는 약이라, 배뇨 증상이 좋아졌다고 마음대로 끊으면 안 돼요.\n\n신부전 환자는 용량을 조절할 필요가 없어요. 크레아티닌청소율 9.0 mL/min 수준의 중증 신부전에서도 약물동력학적으로 유의한 변화가 없었다는 게 허가 기준이에요. 70세 이상 고령자도 약 배설이 약간 감소하긴 하지만 용량 조절은 필요 없어요.\n\n간기능 이상 환자는 신중 투여 대상이에요. 간기능에 이상이 있다면 처방 전 의사에게 반드시 알려야 해요. 코팅 정제를 쪼개거나 분쇄하면 안 돼요. 코팅이 손상되면 임산부가 피부를 통해 흡수했을 때 남성 태아 외부 생식기 발달에 이상을 일으킬 수 있어서, 코팅 상태 그대로 통째로 삼켜야 해요.",
